// Package imagesearch defines the types and the interface of an image search
// against one registry: what to search (Query), where (Target) and what comes
// back (Image). It is pure Go, with no UI and no network code of its own; the
// adapters that talk to a registry implement Searcher elsewhere.
//
// Anonymous Docker Hub search is not covered here (see IS-02).
package imagesearch

import "context"

// Target describes the registry entry a search runs against.
type Target struct {
	EntryKey    string
	Alias       string
	RegistryURL string
	APIURL      string
	RepoPrefix  string
	// Username and Password are empty for an anonymous entry (D12).
	Username string
	Password string
}

// Query is a search request. Limit 0 means the adapter's default.
type Query struct {
	Text  string
	Limit int
}

// Image is one search result.
type Image struct {
	EntryKey string
	Name     string
	// Repo is the final repository path, with the prefix and the library/
	// namespace applied exactly once (D39).
	Repo        string
	Description string
	Stars       int
	// HasStars tells whether Stars is meaningful for this registry.
	HasStars bool
	Official bool
}

// Searcher searches one registry. partial is true when the result is cut short
// (limit, deadline or a page that failed) but still usable.
type Searcher interface {
	Search(ctx context.Context, t Target, q Query) (images []Image, partial bool, err error)
}

// SearcherFunc adapts a function to the Searcher interface.
type SearcherFunc func(ctx context.Context, t Target, q Query) ([]Image, bool, error)

// Search calls f.
func (f SearcherFunc) Search(ctx context.Context, t Target, q Query) ([]Image, bool, error) {
	return f(ctx, t, q)
}
package imagesearch

import (
	"context"
	"errors"
	"slices"
	"testing"
)

var _ Searcher = SearcherFunc(nil)

type ctxKey struct{}

func TestSearcherFuncDelegates(t *testing.T) {
	errBoom := errors.New("boom")
	tests := []struct {
		name    string
		target  Target
		query   Query
		images  []Image
		partial bool
		err     error
	}{
		{"results", Target{EntryKey: "a", Username: "u"}, Query{Text: "nginx", Limit: 5}, []Image{{Name: "nginx", Official: true}}, false, nil},
		{"partial", Target{EntryKey: "b"}, Query{Text: "redis"}, []Image{{Name: "redis"}}, true, nil},
		{"error", Target{}, Query{}, nil, false, errBoom},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			ctx := context.WithValue(context.Background(), ctxKey{}, "v")
			var s Searcher = SearcherFunc(func(c context.Context, tg Target, q Query) ([]Image, bool, error) {
				if c.Value(ctxKey{}) != "v" {
					t.Error("context not forwarded")
				}
				if tg != tt.target {
					t.Errorf("target = %+v, want %+v", tg, tt.target)
				}
				if q != tt.query {
					t.Errorf("query = %+v, want %+v", q, tt.query)
				}
				return tt.images, tt.partial, tt.err
			})
			images, partial, err := s.Search(ctx, tt.target, tt.query)
			if !slices.Equal(images, tt.images) || partial != tt.partial || !errors.Is(err, tt.err) {
				t.Errorf("got (%v, %v, %v), want (%v, %v, %v)", images, partial, err, tt.images, tt.partial, tt.err)
			}
		})
	}
}
}

// normalizeRepoForRegistry prepends "library/" for bare names on Docker Hub.
func normalizeRepoForRegistry(registryURL, repo string) string {
	if strings.Contains(repo, "/") {
		return repo
	}
	if isDockerHub(registryURL) {
		return "library/" + repo
	}
	return repo
}

// registryHost strips the scheme from a configured registry URL, leaving what
// Docker itself is keyed on: `host[:port]`, plus whatever path a repository
// manager serves the registry under.
//
// A registry URL is written either way in practice — the form does not
// normalize it, `registryAPIURL` explicitly accepts both, and this package's own
// examples write `https://nexus.example.com/repository/docker-group`. Every
// Docker-facing use has to strip it, and none of the three that needed to did
// (D39): a `docker pull` reference carrying `https://` is not a reference at
// all, and a hub alias compared against a scheme-bearing string never matched,
// so images from a Hub configured as `https://docker.io` lost their `library/`
// prefix.
func registryHost(registryURL string) string {
	base := strings.TrimSuffix(strings.TrimSpace(registryURL), "/")
	for _, scheme := range []string{"https://", "http://"} {
		if len(base) >= len(scheme) && strings.EqualFold(base[:len(scheme)], scheme) {
			return base[len(scheme):]
		}
	}
	return base
}

// isDockerHub reports whether a registry URL names Docker Hub, under either of
// the two spellings and with or without a scheme. Hub is the one registry whose
// references carry no host, so every caller has to recognise it.
func isDockerHub(registryURL string) bool {
	host := registryHost(registryURL)
	return strings.EqualFold(host, "docker.io") || strings.EqualFold(host, "registry-1.docker.io")
}

